#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <cstring>
#include <cstdint>

using namespace std;

const int BUFFER_SIZE = 1024;

class FastScanner {
private:
    uint8_t buffer[BUFFER_SIZE];
    int lenbuf = 0;
    int ptrbuf = 0;
    istream& is;

    int readByte() {
        if (lenbuf == -1) throw runtime_error("EOF");
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            lenbuf = is.read(reinterpret_cast<char*>(buffer), BUFFER_SIZE).gcount();
            if (lenbuf <= 0) return -1;
        }
        return buffer[ptrbuf++];
    }

    bool isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    int skip() {
        int b = readByte();
        while (b != -1 && isSpaceChar(b)) {
            b = readByte();
        }
        return b;
    }

public:
    FastScanner(istream& input) : is(input) {}

    string nextString() {
        int b = skip();
        string result;
        while (b != -1 && !isSpaceChar(b)) {
            result += static_cast<char>(b);
            b = readByte();
        }
        return result;
    }

    int nextInt() {
        int num = 0;
        int b = readByte();
        bool minus = false;
        while (b != -1 && !(b >= '0' && b <= '9' || b == '-')) {
            b = readByte();
        }
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }
};

void solve(FastScanner& scanner) {
    int n = scanner.nextInt();
    string s = scanner.nextString();
    int r = 0;
    for (int i = 1; i < n; ++i) {
        if (s[i] == s[i-1]) {
            r++;
        }
    }
    cout << r << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    auto start = chrono::high_resolution_clock::now();

    FastScanner scanner(cin);
    solve(scanner);

    auto end = chrono::high_resolution_clock::now();
    auto duration = chrono::duration_cast<chrono::milliseconds>(end - start).count();
    cerr << duration << "ms" << endl;

    return 0;
}
